window.RP_SESSION={"id":"S-ae21e82ac699","messages":[{"id":"RP-0058614","time":"2026-02-28T12:10:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"...\n...\n...","characters":["P-41ba4c5736e6"]},{"id":"RP-0058615","time":"2026-02-28T12:10:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"!자연","characters":["P-41ba4c5736e6"]},{"id":"RP-0058616","time":"2026-02-28T12:10:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'라이아흐 미샤'의 자연 판정 :\n[5, 1, 1] + [1]\n성공수 : [ 1 ]","characters":[]},{"id":"RP-0058617","time":"2026-02-28T12:14:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그렇군요. 개똥지빠귀씨. 반면 다른 분들은...\"\n\n 새들은 변덕이 심하다. 그 삶이 자유로워서인가? 자유에는 책임이 따른다. 그 책임에서 벗어나지 못하는 새들은 좋은 파수꾼이다.\n\n\"모이만 주워먹고... 이러다가 잡아먹어버려요.\"\n\n 아니면 그냥 멍청하거나. 나의 말을 믿지 않는다는듯 새들은 저마다 좋아하는 이야기를 재잘거릴 뿐이다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0058618","time":"2026-02-28T12:16:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"'과연 문제가 없는걸까요? 분명... 흐름이 이상한데...'\n\n'당장 느껴지는 것은 없닷...!'\n\n최근들어 느껴지는 불길한 느낌. 자연스럽지 않고 뭐랄까... 케케묵은 먼지와도 같은... 아니 그보다 숨을 조이는 그런 느낌...!\n\n 무언가 기시감이 느껴지지만 도통 보이지가 않는다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0058619","time":"2026-02-28T12:17:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"시작은 아마 아카쿠가 깨어나지 않은 그 때였던 것으로 기억한다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0058620","time":"2026-02-28T12:20:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"슬쩍 길드 뒷켠의 흙을 파본다. 흙의 습기에 젖어 썩어가는 인형이 나온다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0058621","time":"2026-02-28T12:21:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"어린아이  모양의 인형은 그 부모를 찾기 마련이다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0058622","time":"2026-02-28T12:22:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"그리고  부모는 가장 비슷한 존재일터. 습하고 외진 곳 기묘한 느낌의 인형과 비슷한 존재는 적어도 길드에는 없었다. 그리고 외부에서도 찾아오지는 않은 모양이다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0058623","time":"2026-02-28T12:23:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"썩지않도록 잘 말려서 빻은 숯가루를 뿌리고 인형을 다시 덮는다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0058624","time":"2026-02-28T12:23:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"!자연","characters":["P-41ba4c5736e6"]},{"id":"RP-0058625","time":"2026-02-28T12:23:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'라이아흐 미샤'의 자연 판정 :\n[2, 2, 2] + [3]\n성공수 : [ 0 ]","characters":[]},{"id":"RP-0058626","time":"2026-02-28T12:23:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"곧 썩을 것 같네요... 새로운 인형을 만들어야겠어요.\"","characters":["P-41ba4c5736e6"]},{"id":"RP-0058627","time":"2026-02-28T12:24:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"미샤는 슬쩍 길드 내부로 들어갔다.","characters":["P-41ba4c5736e6"]},{"id":"RP-0058628","time":"2026-02-28T12:24:00+09:00","room":"RP","name":"라이아흐 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-41ba4c5736e6"]},{"id":"RP-0058629","time":"2026-02-28T12:24:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
